    window, wall = fresh_window()
    damper, clock = fresh_damper(window=window)
    damper._armed_until[LABEL] = clock.now - 2.0
    seed_label_doc_here(client, WALL0 + 3.3)
    seed_spill_here(client, WALL0 + 2.6)
    residual, generation = damper.peek(LABEL, client=client)
    assert residual == pytest.approx(3.3, abs=1e-09)
    assert generation == 0
    assert window.reads == 1
    assert window.spill_reads == 0
    assert clock.sleeps == []  # the gate never sleeps


