def test_gate_log_fleet_wins_client_yes(caplog) -> None:
    client = StormDocsClient()
    window, wall = fresh_window()
    damper, clock = fresh_damper(window=window)
    seed_label_doc_here(client, WALL0 + 2.25)
    with caplog.at_level(logging.INFO, logger='database.batch_pipeline_store'):
        damper.peek(LABEL, client=client)
    gate_lines = [record.getMessage() for record in caplog.records if 'scope=gate_' in record.getMessage()]
    assert gate_lines == ['event=batch_store_backoff scope=gate_fleet operation=batch_merge_commit waited_ms=2250']


